--------------------------------------------------------------------------------
-- kgi-ggreport-web — Oracle 정본 (039) : 금고 약정 기록 INST_BANK_CONTRACT + 코드표 BANK·BANK_RANK·BANK_CONTRACT_SRC·BANK_CANCEL_REASON·BANK_ACCOUNT (NEXT 72·88·89, 2026-11-16)
-- 키 = (INSTITUTION_ID, CONTRACT_NO, REV_NO). CONTRACT_NO = 기관 안 약정 줄 번호(1,2,3…), REV_NO = 줄 안 1부터 연속.
-- 추가 전용: 고치기 = 같은 줄의 새 REV 행(ACTION_CD=SAVE), 지우기 = 새 REV 행(ACTION_CD=CANCEL, 값은 직전 행 복사 + 취소 사유).
--   현재 상태 = 줄의 최대 REV 행. 그 행이 CANCEL 이면 그 줄은 취소됨.
-- 줄 번호·REV 발급은 INSTITUTIONS 행 FOR UPDATE 로 직렬화, 복합 PK 가 마지막 방어선(서비스가 409).
-- 참조(서비스가 확인): INSTITUTION_ID -> INSTITUTIONS, EDITOR_EMP_NO -> USERS, BANK_CD -> COMMON_CODE(BANK),
--   RANK_CD -> COMMON_CODE(BANK_RANK), SRC_KIND -> COMMON_CODE(BANK_CONTRACT_SRC), CANCEL_REASON_CD -> COMMON_CODE(BANK_CANCEL_REASON),
--   ACCOUNT_CD -> COMMON_CODE(BANK_ACCOUNT).
--   ACTION_CD·ORIGIN_CD 는 Java 상수(SAVE/CANCEL, MANUAL).
-- 순위 규칙(서비스 검사): 기관 TYPE 이 지자체·교육청이면 FIRST·SECOND 만, 그 밖(법원·공공기관 등)은 NONE·JOINT 만. TYPE 이 비어 있으면(옛 시드) 막지 않는다.
-- 같은 순위(1금고끼리·2금고끼리, 공동 지정은 같은 은행끼리)에서 기간이 겹치면 서비스가 409 DUP_RANK, 확인 후 저장하면 OVERLAP_CONFIRMED=1.
-- 맡는 회계(ACCOUNT_CD·ACCOUNT_ETC)는 지자체·교육청 약정에서만 받는다(선택).
-- TERM_FROM·TERM_TO = YYYY | YYYY-MM | YYYY-MM-DD(원문이 연도만인 경우가 많음). CHECKED_DATE = YYYY-MM-DD.
-- ⚠️ 수정자 사번·이름·시각·EMP_VERIFIED 는 서버가 Actor 로 채운다. EMP_VERIFIED=0 = X-Emp-No 자기신고(위조 가능) — '검증됨'으로 표시하지 않는다.
-- ⚠️ SCREEN_ID·BUTTON_ID 도 자기신고 머리글(허용 목록 밖은 UNKNOWN, UI_VALID=0).
-- ⚠️ NOTE·CHECKED_DEPT·BANK_NAME_ETC·ACCOUNT_ETC·CANCEL_REASON_ETC 는 개인정보·정당·전화번호를 서버가 거르고, CHECKED_DEPT 는 사람 이름+직함도 거른다(부서명만).
-- ⚠️ DB 권한(DBA): INST_BANK_CONTRACT 는 SELECT·INSERT 만(UPDATE·DELETE 없음).
-- ⚠️ 코드표 은행 이름은 data-auditor 2026-11-10·11-16 정리 기준(정식명 확정 전) — 바꿀 때는 CODE_NAME UPDATE, 삭제 금지(016).
--   X01·X02 는 ENABLED=0(새로 고를 수 없고 옛 값 표시용).
-- ⚠️ 멱등하지 않다. 016·017 뒤 한 번만(038 다음). 적용한 뒤에는 이 파일을 고치지 않는다(체크섬).
-- 되돌리기(데이터 소멸, 운영 금지): DROP TABLE INST_BANK_CONTRACT;
--   DELETE FROM COMMON_CODE WHERE CODE_GROUP IN ('BANK','BANK_RANK','BANK_CONTRACT_SRC','BANK_CANCEL_REASON','BANK_ACCOUNT');
--------------------------------------------------------------------------------

CREATE TABLE INST_BANK_CONTRACT (
    INSTITUTION_ID     VARCHAR2(64 CHAR)   NOT NULL,
    CONTRACT_NO        NUMBER(6)           NOT NULL,
    REV_NO             NUMBER(6)           NOT NULL,
    ACTION_CD          VARCHAR2(10 CHAR)   NOT NULL,   -- SAVE | CANCEL
    ORIGIN_CD          VARCHAR2(10 CHAR)   NOT NULL,   -- MANUAL(화면 직접 입력). 수집 반입·입찰 결과(73)는 나중
    RANK_CD            VARCHAR2(20 CHAR)   NOT NULL,   -- BANK_RANK
    BANK_CD            VARCHAR2(10 CHAR)   NOT NULL,   -- BANK
    BANK_NAME_ETC      VARCHAR2(30 CHAR),              -- BANK_CD='ETC' 일 때만
    TERM_FROM          VARCHAR2(10 CHAR),
    TERM_TO            VARCHAR2(10 CHAR)   NOT NULL,
    SRC_KIND           VARCHAR2(20 CHAR)   NOT NULL,   -- BANK_CONTRACT_SRC
    SRC_URL            VARCHAR2(500 CHAR),
    SRC_NO             VARCHAR2(50 CHAR),
    CHECKED_DATE       VARCHAR2(10 CHAR)   NOT NULL,   -- 확인일(오늘 이후 불가)
    CHECKED_DEPT       VARCHAR2(50 CHAR),              -- 담당자 확인일 때 필수(기관 부서명, 사람 이름 금지)
    NOTE               VARCHAR2(100 CHAR),             -- 비고
    ACCOUNT_CD         VARCHAR2(20 CHAR),              -- BANK_ACCOUNT. 지자체·교육청만(선택)
    ACCOUNT_ETC        VARCHAR2(30 CHAR),              -- ACCOUNT_CD='ETC' 일 때만
    OVERLAP_CONFIRMED  NUMBER(1)           DEFAULT 0 NOT NULL,  -- 1 = 같은 순위 기간 겹침을 알고 저장함(confirm_overlap)
    CANCEL_REASON_CD   VARCHAR2(20 CHAR),              -- ACTION_CD='CANCEL' 일 때만. BANK_CANCEL_REASON
    CANCEL_REASON_ETC  VARCHAR2(50 CHAR),              -- CANCEL_REASON_CD='ETC' 일 때만
    EDITOR_EMP_NO      VARCHAR2(7 CHAR)    NOT NULL,
    EDITOR_NAME        VARCHAR2(50 CHAR)   NOT NULL,   -- 그때 이름 스냅샷
    EMP_VERIFIED       NUMBER(1)           DEFAULT 0 NOT NULL,
    SCREEN_ID          VARCHAR2(30 CHAR)   NOT NULL,
    BUTTON_ID          VARCHAR2(30 CHAR)   NOT NULL,
    UI_VALID           NUMBER(1)           DEFAULT 0 NOT NULL,
    SAVED_AT           VARCHAR2(40 CHAR)   NOT NULL,   -- Times.nowIso
    CONSTRAINT PK_INST_BANK_CONTRACT PRIMARY KEY (INSTITUTION_ID, CONTRACT_NO, REV_NO)
);
CREATE INDEX IDX_IBC_EDITOR ON INST_BANK_CONTRACT (EDITOR_EMP_NO, SAVED_AT);

